// El vocabulario del juego no se traduce: una sola fuente para los cinco
// diccionarios. La política, con su medición y sus exclusiones, en src/jerga.js.
import { JERGA } from './jerga.js';

/**
 * Traducción de la aplicación.
 *
 * Un único diccionario plano por idioma. Todo lo que ve o escucha el usuario
 * pasa por t(); si falta una clave se cae al español y, si tampoco está, se
 * devuelve la propia clave para que el hueco se vea en vez de quedar en blanco.
 *
 * Las banderas van como SVG en línea: los emoji de bandera no se dibujan en
 * Windows, que muestra las dos letras del país en su lugar.
 */

