  'rp.noLineas': 'Esta pelea ya no está en tu registro, así que no se puede reproducir. Las líneas son la fuente: sin ellas, cualquier reproducción estaría colocada a ojo.',
  'log.note': 'Las líneas del fichero entre el principio y el final de esta pelea, tal cual. Todo lo que enseña la aplicación son cuentas sobre esto.',
