  'row.pace': 'ritmo',
  'row.paceNote': 'Tu daño partido por los segundos en los que de verdad hiciste algo. El número grande de arriba es otra cosa: el daño partido por la pelea entera, que es lo que pones en el reloj del grupo. Un lanzador que entra tarde puede tener un ritmo altísimo y aportar poco.',
  'tank.note': 'Cuánto llegó y cuánto se quedó en la armadura. NO dice si estuviste cerca de morir: el registro no da la vida de nadie, así que 3.000 recibidos son una tragedia con 3.100 de vida y un paseo con 12.000, y esto no sabe cuál de las dos.',
  'tank.who': 'quién',
  'tank.stopped': 'lo que no entró',
  'tank.stoppedN': 'parados',
  'tank.absorbed': 'absorbido',
  'tank.inRunes': 'en {n}',
  'tank.runeNote': 'La absorción son runas que se comen el golpe entero. En todo lo que se enseña aquí hay {n}: es una cifra bruta y no se saca ningún porcentaje de ella, porque con tan pocas no significaría nada.',
  'casts.title': 'Qué lanzó cada uno',
  'casts.note': 'Una raya por lanzamiento, colocada en el segundo en que pasó. Cada fila es un lanzador, porque la pregunta suele ser de quién y no de cuándo: una fila medio vacía es alguien que no estaba usando lo suyo. Pasa el ratón por una raya para ver qué fue.',
  'casts.cut': 'Y {n} lanzamientos más que no caben en lo guardado de esta pelea.',
  'up.title': 'Cuánto tiempo estuvo puesto',
  'up.note': 'Medido de tu lanzamiento a su caída, y no de la entrada a la caída: la línea de caída dice de qué hechizo es, la de entrada no dice de ninguno. Relanzar antes de que caiga no cuenta dos veces.',
  'up.before': 'ya puesto',
  'up.beforeNote': 'Cayó dentro de esta pelea pero no consta que lo lanzaras en ella: venía puesto de antes, así que se cuenta desde el principio.',
  'up.open': 'sin caer',
  'up.openNote': 'Lo lanzaste y no cayó antes de acabar la pelea. Si hubiera caído habría línea, así que se cuenta hasta el final.',
  'up.blind': 'Lo que ni se lanzó ni cayó dentro de esta pelea no aparece: un buff que te pusieron antes y seguía al acabar no deja ninguna línea aquí, y no se cuenta ni como 0% ni como 100%. Y no se mide maná ni vigor, que el registro de EQL no los da.',
  'marks.openNote': 'Cada marca abre la pelea en la que la hiciste: pulsa una y se ve entera en Combate.',
  'marks.onlyOne': 'una sola pelea',
  'marks.median': 'mediana',
  'marks.note': 'Agrupadas por nivel a propósito: comparar una pelea de hoy con el récord de cuando ibas más alto sólo informa de que ya no vas a ese nivel.',
  'foe.byDiff': 'Por dificultad',
  'foe.castIn': 'Lo que lanzó en los {n} encuentros',
  'foe.castIn_1': 'Lo que lanzó en el único encuentro',
  'foe.castNote': 'En EQL las clases secundarias de un enemigo se sortean por instancia, así que dos encuentros con el mismo nombre pueden ser enemigos distintos. Y que algo no aparezca no prueba que no lo tenga: los NPC respetan tiempos de reutilización. Por eso va «en cuántos de cuántos» y no como lista de sus habilidades.',
  'foe.inFights': 'en {n} de {total}',
  'foe.diffNote': 'En EQL cada instancia tiene una dificultad y los enemigos cambian de verdad: más vida, más daño y hechizos que en dificultades bajas no tienen. Promediarlas describiría un enemigo que no existe.',
  'foe.noDiff': 'sin dificultad',
  'foe.resistNote': 'Las resistencias van juntas a propósito: en lo medido apenas se distinguen entre dificultades, y separarlas partiría una muestra ya corta.',
  'cat.title': 'Catálogo de hechizos',
  'cat.open': 'Ver mis hechizos',
  'cat.note': 'Construido sólo desde tus peleas. El log no da el coste en maná ni el tiempo de lanzamiento, y de lo que nunca has lanzado no hay nada.',
