  'cat.unknownHealNote': 'El registro no dijo de qué hechizo vino esta curación. No es un hechizo llamado «cura»: es lo que no se pudo identificar.',
  'cat.alsoHeals': 'Además cura {n}. Sale de las líneas de curación, que hasta ahora no se leían aquí.',
