  'mig.title': 'Tu histórico se guardó con cifras incorrectas',
  'mig.body': 'En las {n} peleas guardadas por tu versión anterior, el botín se colgó de la pelea que estaba abierta al recogerlo y no del cadáver del que salió —y se saquea después de matar—. Sobre un histórico real eso son 34 objetos colgados de una pelea posterior y 273 con el instante fuera de la suya, que el reproductor no llegaba a enseñar. Además no se guardaba la moneda de los cadáveres, que sí está en el registro. Nada de esto se puede recomponer leyendo lo guardado: dónde iba cada objeto se decidió al escribirlo.',
