  'rp.noLineas': 'This fight is no longer in your log, so it cannot be replayed. The lines are the source: without them any replay would be placed by eye.',
  'log.note': 'The file\u2019s lines between the start and the end of this fight, as they are. Everything the app shows is counts over this.',
  'log.loading': 'Reading the log\u2026',
  'log.cut': 'There are {n} more lines that do not fit here. They are cut from the end.',
  'log.noTime': 'This fight does not store its time, so its lines cannot be looked up.',
  'log.err.sin-fichero': 'The log is no longer where it was: there are no lines to show.',
  'log.err.fuera-de-rango': 'This fight is not in the log you have open. It may come from another file, or from one that rotated.',
