  'log.err.error': 'The log could not be read.',
  'log.outOfRangeSpan': 'The open file runs from {desde} to {hasta}.',
  'row.pace': 'pace',
  'row.paceNote': 'Your damage divided by the seconds you were actually doing something. The big number above is a different thing: damage divided by the whole fight, which is what you put on the group\'s clock. Someone who joins late can have a huge pace and contribute little.',
  'tank.note': 'How much got through and how much stopped at your armour. It does NOT say whether you were close to dying: the log gives nobody\'s health, so 3,000 taken is a disaster at 3,100 HP and a stroll at 12,000, and this cannot tell which.',
  'tank.who': 'who',
  'tank.stopped': 'what did not land',
  'tank.stoppedN': 'stopped',
  'tank.absorbed': 'absorbed',
  'tank.inRunes': 'in {n}',
  'tank.runeNote': 'Absorption is runes eating a whole hit. Everything shown here comes from {n} of them: it is a raw figure and no percentage is drawn from it, because with so few it would mean nothing.',
  'casts.title': 'What each one cast',
  'casts.note': 'One tick per cast, placed at the second it happened. Each row is one caster, because the usual question is who rather than when: a half-empty row is someone who was not using their kit. Hover a tick to see what it was.',
  'casts.cut': 'And {n} more casts that do not fit in what is stored for this fight.',
  'up.title': 'How long it stayed up',
  'up.note': 'Measured from your cast to its fade, not from the land to the fade: the fade line names the spell, the landing line names none. Recasting before it drops does not count twice.',
  'up.before': 'already up',
  'up.beforeNote': 'It faded inside this fight but there is no record of you casting it here: it was already up, so it counts from the start.',
  'up.open': 'never faded',
  'up.openNote': 'You cast it and it did not fade before the fight ended. Had it faded there would be a line, so it counts to the end.',
  'up.blind': 'Anything neither cast nor faded inside this fight does not appear: a buff put on you before and still up at the end leaves no line here, and counts as neither 0% nor 100%. And mana and endurance are not measured — the EQL log gives neither.',
  'marks.openNote': 'Each mark opens the fight where you set it: click one and it shows in full under Combat.',
  'marks.onlyOne': 'a single fight',
  'marks.median': 'median',
  'marks.note': 'Grouped by level on purpose: comparing a fight today against the record from when you were higher only tells you that you are no longer at that level.',
  'foe.byDiff': 'By difficulty',
  'foe.castIn': 'What it cast across {n} encounters',
  'foe.castIn_1': 'What it cast in the single encounter',
  'foe.castNote': 'In EQL an enemy’s secondary classes are rolled per instance, so two encounters with the same name may be different creatures. And something not showing up does not prove it lacks it: NPCs respect reuse timers. Hence «in how many out of how many», rather than a list of its abilities.',
  'foe.inFights': 'in {n} of {total}',
  'foe.diffNote': 'In EQL every instance has a difficulty and the enemies genuinely change: more health, more damage, and spells they do not have at lower difficulties. Averaging them would describe a monster that does not exist.',
  'foe.noDiff': 'no difficulty',
  'foe.resistNote': 'Resistances are kept together on purpose: in what has been measured they barely differ between difficulties, and splitting them would break an already small sample.',
  'cat.title': 'Spell catalogue',
  'cat.open': 'See my spells',
  'cat.note': 'Built only from your fights. The log gives neither mana cost nor cast time, and there is nothing at all for what you have never cast.',
  'cat.spell': 'Spell',
  'cat.type': 'Type',
  'cat.uses': 'Uses',
