  'cat.healed': 'healing',
  'cat.healAvg': 'average healing',
  'cat.damage': 'damage',
  'cat.crits': 'crits',
  'cat.max': 'max',
  'cat.inFights': 'fights',
  'cat.ds': 'damage shield',
  'cat.unknownHeal': 'unidentified healing',
  'cat.dsNote': 'Not something you cast: it fires on its own when you get hit. That is why it has no usage rhythm and no cooldown.',
  'cat.unknownHealNote': 'The log did not say which spell this healing came from. It is not a spell called «heal»: it is what could not be identified.',
  'cat.alsoHeals': 'It also heals {n}. This comes from the healing lines, which were not read here until now.',
  'cat.drainNote': 'It does both, and both are measured. Counting only the damage describes half of what it does.',
  'cat.levelsNote': 'You have used it at levels {levels}. Figures are split by level: merging them would measure the level jump, not the spell.',
  'cat.byTranche': 'Tranche by tranche',
  'cat.trancheNote': 'One bar per fight, in order but with no time scale: between two fights there may be ten seconds or two days. Split by level and difficulty, and only with {n} fights or more.',
  'cat.noTranche': 'No tranche reaches {n} fights, so none is drawn. Below that there are points, not a trend.',
  'cat.dropped': '{n} tranches left out for a short sample, {f} fights in total',
  'cat.vsFoes': 'What it lands on',
  'cat.vsFoesNote': 'Each enemy with its difficulty beside it: the same spell can always land at D0 and be resisted at D4.',
  'cat.fewUses': 'small sample: {n} uses',
  'cat.cdTitle': 'Measured reuse',
  'cat.cdAttempts': 'too-early warnings',
  'cat.cdUses': 'uses',
  'cat.cdNote': 'The warning states the time REMAINING, not the full reuse: it appears when you try too early. What is here is a lower bound.',
  'cat.notCountable': 'Whether you make good use of it cannot be known: it leaves no trace in the log when used, only when it fails for being on cooldown.',
  'cat.oneSample': 'a single sample',
