  'mig.title': 'Your history was saved with incorrect figures',
  'mig.body': 'In the {n} fights saved by your previous version, loot was attached to whichever fight was open when you picked it up rather than to the corpse it came from — and you loot after killing. On a real history that means 34 items hanging off a later fight and 273 whose moment falls outside their own, which the replay never got to show. Coin from corpses was not saved at all, though the log records it. None of this can be recomposed from what is stored: where each item went was decided when it was written.',
  'mig.fix': 'It can be fixed by re-reading your log, which takes a few seconds. What you have now is kept aside just in case.',
  'mig.button': 'Rebuild history',
  'mig.working': 'Re-reading the log…',
  'mig.doneTitle': 'History rebuilt',
  'mig.done': '{fights} fights · {kills} enemies killed · {lines} lines re-read in {secs} s. The previous files are kept as {backup}.',
  'mig.podadas': 'And {n} files from older rebuild backups were deleted. The 3 most recent batches are kept: {tandas}.',
