  'mig.fail.sin-log': 'I cannot find your log file. Set it up under «Change log» and try again.',
  'mig.fail.sin-peleas': 'Your log no longer contains those fights, so rebuilding would have deleted them. Nothing was touched.',
  'mig.fail.sin-permisos': 'I cannot write to the data folder.',
