  'enc.deathsRate': 'of your fights',
  'enc.deathsNote': 'The enemy shown beside each one is the one that dealt you the MOST DAMAGE in that fight, not the one that landed the killing blow: the log never says which it was, and it may well have been the one that hit you least.',
  'enc.deathsByZone': 'Where you fall', 'enc.deathsByFoe': 'Who hit you hardest when you fell',
