  'sn.channeler': 'Cover against mixed damage, and better channelling. Half the endurance per point, but it taxes mana.',
  'sn.evasive': 'Evades 95% of incoming attacks, but fails once you run out of endurance.',
  'sn.offensive': 'Doubles melee damage. Below 25% endurance you lose accuracy.',
  'sn.striker': 'Multiplies combat skills, not auto-attack.',
  'sn.ranged': 'No minimum range, and ranged attacks can double and triple.',
  'sn.berserker': 'Doubles attack speed, but you take 8.3% of your own damage.',
  'iv.arcanemastery': 'Cuts cast and recovery time by 20%, plus 10% per extra intelligence class.',
  'iv.divine': 'Mana spent heals the group member lowest on health. Turns any spending into passive healing.',
  'iv.empower': 'Spell damage +20% (and +10% per extra non-hybrid casting class) for 20% more mana.',
  'iv.inversion': 'Shifts two thirds of cast time into global recovery: less exposure to interrupts.',
  'iv.inviolable': 'Spells can\u2019t be interrupted, at double mana plus the same again in endurance.',
  'iv.overchannel': '\u2212150 resist adjust, plus \u221215 per non-hybrid casting class. For enemies that resist you a lot.',
