  'tg.origen.plantillaHint': 'Il vient avec l’application et n’a PAS été vérifié contre votre journal. Les emotes exactes d’EQL ne sont documentées nulle part : un modèle dit ce qu’il DEVRAIT attraper, pas ce qu’il attrape.',
