  'tg.vistasHint': 'Combien de fois il a réellement correspondu depuis que l’application surveille. C’est la différence entre une promesse et un fait : un motif qui ne correspond jamais ressemble à une alarme active et n’en est pas une.',
  'tg.aviso.plantillas': 'Les modèles sont des exemples qui fonctionnent, pas des règles vérifiées. Ceux qui nomment un boss doivent être vérifiés contre votre propre journal : mettez le boss que vous combattez et regardez si le compteur monte.',
  'tg.ejemplo': 'exemple',
  'tg.ejemploHint': 'Ligne d’exemple pour tester le motif. Ce n’est pas un déclencheur enregistré et cela ne vient pas de votre journal : c’est une vraie ligne d’EverQuest pour en montrer la forme.',
  'tg.note.castAny': 'Inutilisable tel quel : dans un combat avec des renforts, il se déclenche des dizaines de fois. Pour les sorts importants, utilisez « Sorts ennemis » dans les réglages vocaux, qui filtre par catégorie et n’avertit que pour les ennemis. Ce modèle sert à surveiller UN lanceur précis.',
  'tg.note.bossCast': 'Changez le nom pour celui du boss que vous combattez. Sans minuteur à dessein : le journal n’écrit jamais le temps de recharge d’un sort ennemi, donc il ne peut pas se lire — il faut le chronométrer en jouant et le mettre ici.',
  'tg.note.petDead': 'La mort de votre familier est déjà annoncée toute seule dans les réglages vocaux. Ce modèle sert à surveiller quelqu’un de précis : mettez son nom exact ou il se déclenchera à chaque mort.',
  'tg.patternHelp': 'Avec ${1}\u2026${9} vous insérez les groupes capturés dans la voix et le texte, et ${line} est la ligne entière. EQL nomme le sort dans le journal, donc ^Lady Vox begins casting (.+?)\\.$ vous donne le sort dans ${1}.',
