  'an.limits': 'Le journal n\u2019enregistre ni vie, ni vigueur, ni mana, ni positions. Il ne juge donc jamais si un soin est arrivé trop tard ou si tu as manqué de vigueur : seul ce qui se mesure est affirmé.',
