  'an.accion.contextoNote': 'Ni l\u2019un ni l\u2019autre : c\u2019est ce qui t\u2019est arriv\u00e9. C\u2019est l\u00e0 parce que \u00e7a explique le r\u00e9sultat, pas parce qu\u2019il y a quelque chose \u00e0 corriger.',
  'an.downtimeDetail': 'Tu es rest\u00e9 {s} secondes \u00e0 l\u2019arr\u00eat en trop, {pct}% du combat. C\u2019est mesur\u00e9 sur ta propre cadence, ici {cad} s entre attaques : les trous de cette taille viennent de ton arme et ne comptent pas.',
