  'wz.1.title': 'Bienvenue',
  'wz.1.body': 'Ceci mesure tes dégâts en direct, te dit quelle posture convient à ce qui te frappe, lit le chat à voix haute et décortique les gros combats pour montrer ce qui aurait pu mieux se passer.',
  'wz.1.lang': 'Choisis ta langue',
  'wz.1.time': 'La mise en route prend deux minutes.',
  'wz.2.title': 'Active le journal dans le jeu',
  'wz.2.body': 'EverQuest n\u2019écrit rien sur le disque tant que tu ne le demandes pas. Sans cette étape, il n\u2019y a rien à lire.',
  'wz.2.cmd': 'Tape ceci dans le chat du jeu',
  'wz.2.filters': 'Et maintenant l\u2019important : Options \u2192 Filters',
  'wz.2.filtersBody': 'Mets TOUT ce qui touche aux dégâts au détail maximum, les tiens comme ceux des autres. Si les dégâts des autres restent « abrégés », le jeu ne les écrit pas et ton groupe apparaît à zéro. C\u2019est l\u2019erreur la plus fréquente et la plus difficile à voir, car l\u2019application semble fonctionner.',
  'wz.2.done': 'C\u2019est fait',
  'wz.3.title': 'Trouve ton fichier journal',
  'wz.3.body': 'Tous les disques sont fouillés automatiquement. Avec plusieurs personnages, choisis celui auquel tu joues : le nom du fichier porte le personnage et le serveur.',
  'wz.3.none': 'Rien trouvé. Vérifie que tu as tapé /log on et joué un moment, ou cherche-le à la main.',
  'wz.3.history': 'Lire aussi les combats déjà enregistrés',
  'wz.4.title': 'Dis-moi tes classes',
  'wz.4.body': 'Chaque classe a certaines postures et pas d\u2019autres. Sans elles je ne peux pas te conseiller, et le journal ne tranche pas toujours : Shadow Knight et Paladin partagent les mêmes et sont indiscernables.',
  'wz.4.who': 'Tape /who dans le jeu et elles se remplissent toutes seules. Je lis déjà ton journal.',
  'wz.4.read': 'Lues depuis ton /who : {classes}',
  'wz.4.waiting': 'En attente que tu tapes /who\u2026',
  'wz.5.title': 'Ton familier',
  'wz.5.body': 'Dans EQL ton familier change de nom à chaque invocation, il ne peut donc pas être reconnu de mémoire.',
  'wz.5.cmd': 'Tape ceci une fois, le familier sorti',
  'wz.5.body2': 'Il répondra en donnant son maître et sera identifié. Sinon, l\u2019application te le demandera dès qu\u2019elle verra quelqu\u2019un combattre à tes côtés. Pas de familier ? Passe cette étape.',
  'wz.6.title': 'L\u2019overlay',
  'wz.6.body': 'Une petite fenêtre toujours au-dessus du jeu avec les chiffres en direct. Elle s\u2019atténue hors combat et prévient quand ta posture n\u2019est pas la meilleure.',
  'wz.6.fullscreen': 'Nécessite EQL en fenêtre ou sans bordure : Windows ne dessine rien par-dessus le plein écran exclusif.',
  'wz.6.open': 'Ouvrir l\u2019overlay maintenant',
