  'enc.deathsRate': 'des combats',
  'enc.deathsNote': 'L\u2019ennemi affiché à côté est celui qui t\u2019a fait le PLUS DE DÉGÂTS dans ce combat, pas celui qui a porté le coup fatal : le journal ne le dit pas, et ce peut très bien être celui qui t\u2019a le moins touché.',
