  'enc.progressNote': 'Il n\u2019y a pas de courbe de dps dans le temps, volontairement : elle monte quand tu montes de niveau et descend quand tu affrontes plus coriace, donc elle mesure les deux à la fois et aucune. Ce qui se compare, c\u2019est le même ennemi, à la même difficulté et au même niveau.',
