  'enc.lootNote': '« 2 en 9 morts » est deux chiffres mesurés côte à côte — les fois où tu l\u2019as abattu et les fois où il a lâché ça —, pas un taux de butin : cela mélange toutes les difficultés, car le journal attribue l\u2019objet à un nom et non à une instance.',
