  'enc.zonesNote': 'Cinq difficultés, de 0 à 4 ; la 0 est le monde ouvert. Chaque case compte les ennemis sur lesquels tu as des données pour les avoir affrontés là, à cette difficulté. Une case vide ne dit pas qu\u2019il n\u2019y a rien : elle dit que tu n\u2019y es pas entré.',
