  'det.petLine': 'C\u2019est le familier repli\u00e9 dans toi : la somme de toutes ses attaques, pas une seule. D\u2019o\u00f9 l\u2019absence de m\u00e9diane et d\u2019\u00e9cart. Son d\u00e9tail est l\u00e0 si tu d\u00e9sactives le regroupement des familiers.',
