  'det.shapeOld': 'Ce combat a \u00e9t\u00e9 enregistr\u00e9 avant que la forme du coup ne soit compt\u00e9e, il ne la porte donc pas. Reconstruis l\u2019historique pour la lui donner.',
  'det.twoModes': '2 modes',
  'det.twoModesTip': 'Les coups portant ce nom se regroupent en deux amas s\u00e9par\u00e9s, et ce ne sont pas les critiques : ceux-l\u00e0 sont compt\u00e9s dans leur colonne.',
  'det.twoModesNote': 'Sous {list} il peut y avoir deux choses diff\u00e9rentes. Les coups se regroupent en deux amas s\u00e9par\u00e9s avec un creux vide entre eux, et ce ne sont pas les critiques \u2014compt\u00e9s \u00e0 part\u2014 : d\u2019ordinaire deux armes, ou deux attaques que le journal nomme pareil. Si c\u2019est le cas, la moyenne de cette ligne n\u2019en d\u00e9crit aucune des deux.',
