  'adv.needClassesHint': 'Sans elles je ne peux pas conseiller : chaque classe a certaines postures et pas d\u2019autres. Le journal ne suffit pas toujours : Shadow Knight et Paladin partagent Defensive, Mage Hunter et Spellblade, donc les postures seules ne les distinguent pas. Elles se lisent aussi dans ton /who.',
