  'adv.byStance': 'Ce que tu as évité, posture par posture', 'adv.notSegmented': 'Combat enregistré avant que les dégâts ne soient répartis par posture : le verdict est calculé contre une seule.',
  'mig.fronteras': 'Avertissement : la reconstruction ne reproduit pas exactement ton historique. L’où l’écart entre deux combats fait exactement 20 s, ils peuvent être fusionnés ou découpés autrement, et leurs chiffres changent avec eux. Les fichiers précédents sont mis de côté et récupérables.',
