  'mod.body': 'À l’ouverture de cette version, les {n} combats que tu avais ont été recalculés à la lecture. Tu n’as rien cliqué, et ce n’était pas nécessaire.',
  'mod.why': 'La mitigation de posture était annulée sur les dégâts sur la durée et les boucliers de dégâts ; mesuré sur le journal, la posture ne les réduit pas. Cela gonflait les dégâts subis affichés.',
  'mod.mixed': 'L’historique reste mélangé à dessein : ce qui se corrige à la lecture se corrige, le reste non. D’où le message « combat enregistré avant que les dégâts ne soient répartis par posture » sur les anciens combats. C’est correct.',
