  'pet.mineNote': 'Werden zwischen Sitzungen gemerkt und haben Vorrang vor dem, was das Log erkennt. In EQL werden Namen zwischen Spielern wiederverwendet — hört einer auf, deiner zu sein, entferne ihn besser hier.',
