  'wz.classNote': 'In EQL kannst du dein Klassentrio wechseln, und das Log meldet es nirgends. Die Anwendung leitet es aus den exklusiven Zaubern ab, die du wirkst, aber /who nach jedem Wechsel zu tippen ist das, was die Historie korrekt hält: nur das nennt Stufe und vollständiges Trio.',
  'wz.petNote': 'In EQL bekommt dein Begleiter bei jeder Beschwörung einen neuen Namen, und das Log sagt es auch nicht. Tippe /pet who leader, wenn du einen neuen beschwörst, dann wird er in der ganzen Historie erkannt; sonst erscheint er als Fremder, der deine Gegner schlägt.',
  'lvl.mixed': 'Gemessen auf Stufe {levels}. In EQL ist deine effektive Stufe die der niedrigsten Klasse deines Trios, ein Klassenwechsel senkt sie also komplett. Die Widerstände bleiben zusammen: es gibt keine Stichprobe, um sie nach Stufe zu trennen.',
  'lvl.unknown': 'Stufe unbekannt',
