  'per.title': 'Deine Stufe im Lauf der Zeit',
  'per.note': 'Kein Anstieg: in EQL senkt der Tausch einer Klasse gegen eine niedrigere deine Stufe, das hier sind also Abschnitte und die Linie geht hoch und runter. Jeder öffnet den besten Kampf darin.',
