  'rp.botin.moneda': 'Münzen',
  'rp.botin.monedaNota': 'Münzen hängen an dem Kampf, der gerade offen war, nicht an einer Leiche: das Log sagt nicht, von wem sie stammen.',
  'rp.botin.cadaverNota': 'Jeder Gegenstand geht an den Kampf, in dem seine Leiche starb. Das Log nummeriert Leichen nicht, die Zuordnung läuft über Namen und Nähe: abgeleitet, nicht gemessen.',
  'rp.botin.nadaConMuertos': 'Keine Beute verzeichnet.',
  'rp.botin.nadaConMuertosSub': '{n} Gegner fielen und das Log verzeichnet keine Aufnahme von dir. Nichts mitgenommen und nichts gefallen sehen im Log gleich aus.',
  'rp.botin.nadaSinMuertos': 'Niemand fiel: es gab nichts zu plündern.',
  'rp.botin.nadaSinMuertosSub': 'Ohne Leiche ist keine Beute möglich, also fehlt hier nichts.',
