  'tg.ignoreCase': 'Groß-/Kleinschreibung ignorieren',
  'tg.origen.plantilla': 'Werksvorlage',
  'tg.origen.tuyo': 'von dir geschrieben',
  'tg.origen.plantillaHint': 'Sie kommt mit der Anwendung und wurde NICHT gegen dein Log geprüft. Die genauen Emotes von EQL sind nirgends dokumentiert: eine Vorlage sagt, was sie fangen SOLLTE, nicht was sie fängt.',
  'tg.origen.tuyoHint': 'Du hast ihn geschrieben. Das Programm hat dazu keine Meinung.',
  'tg.vistas': '{n}-mal seit dem Start gesehen',
  'tg.vistasOtro': '{n}-mal gesehen, aber in einem anderen Log',
  'tg.vistasNunca': 'hat in dieser Sitzung noch nicht getroffen',
  'tg.vistasHint': 'Wie oft er tatsächlich getroffen hat, seit die Anwendung mitliest. Das ist der Unterschied zwischen einem Versprechen und einer Tatsache: ein Muster, das nie trifft, sieht aus wie ein aktiver Alarm und ist keiner.',
  'tg.aviso.plantillas': 'Vorlagen sind funktionierende Beispiele, keine geprüften Regeln. Die mit einem Bossnamen musst du gegen dein eigenes Log prüfen: trag den Boss ein, den du wirklich kämpfst, und schau, ob der Zähler steigt.',
  'tg.ejemplo': 'Beispiel',
  'tg.ejemploHint': 'Beispielzeile zum Testen des Musters. Kein gespeicherter Auslöser und nicht aus deinem Log: eine echte EverQuest-Zeile, damit du die Form siehst.',
  'tg.note.castAny': 'So unbrauchbar: in einem Kampf mit Adds feuert er Dutzende Male. Für wichtige Zauber nimm „Gegnerische Zauber“ in den Sprachoptionen, das nach Kategorie filtert und nur vor Gegnern warnt. Diese Vorlage ist für EINEN bestimmten Zauberer.',
  'tg.note.bossCast': 'Ändere den Namen auf den Boss, den du wirklich kämpfst. Absichtlich ohne Timer: das Log schreibt die Wiederverwendungszeit eines gegnerischen Zaubers in keiner Zeile, sie lässt sich also nicht lesen — du musst sie im Spiel stoppen und hier eintragen.',
  'tg.note.petDead': 'Der Tod deines Begleiters wird in den Sprachoptionen schon von allein angesagt. Diese Vorlage ist für jemand Bestimmten: trag den genauen Namen ein, sonst feuert sie bei jedem Tod.',
  'tg.patternHelp': 'Mit ${1}\u2026${9} setzt du die erfassten Gruppen in Stimme und Text ein, ${line} ist die ganze Zeile. EQL nennt den Zauber im Log, also liefert ^Lady Vox begins casting (.+?)\\.$ den Zauber in ${1}.',
  'tg.speak': 'Laut vorlesen',
