  'share.tip': 'Copia este combate para colar no chat do jogo: uma linha com a divisão dos teus e outra com os inimigos. O chat não respeita quebras de linha, por isso cola-as em separado.',
  'share.prefixTitle': 'Texto à frente de cada linha copiada',
  'share.prefixNote': 'Vazio por omissão: no chat de grupo já se percebe do que é, e são caracteres que no limite contam. Num canal com muito tráfego, algo como «[EQL]» ajuda.',
  'share.prefixPh': 'nada',
  'share.pctTitle': 'Como se escreve a divisão',
  'share.pctNote': 'Verificado dentro do jogo: o «%» passa para o chat sem problema. Fica a alternativa caso algum cliente o trate de outra forma — é o prefixo de substituição das macros, e nem todos se comportam igual.',
  'share.petsTitle': 'Os familiares ao copiar',
  'share.petsNote': 'Solto e ordenado por dano, um familiar parece mais um jogador do grupo. Medido num combate real: «Campeon 15363 (40%)» com o familiar três lugares abaixo descreve duas pessoas onde há uma; somados são 23388, 61%, e a divisão muda de ordem. Somar marca-se com «+pet» para ninguém ler o número como dano só teu.',
  'share.petsMerge': 'somado ao dono (Campeon +pet)',
