  'pet.isMineNote': 'É o teu familiar. Escolhe «ninguém» na lista para o largar.',
  'pet.mineTitle': 'Familiares que declaraste teus',
  'pet.mineNote': 'Lembram-se entre sessões e mandam sobre o que o registo detetar. No EQL os nomes reciclam-se entre jogadores, por isso se um deixar de ser teu convém tirá-lo daqui.',
  'pet.mineEmpty': 'Nenhum declarado à mão: só o que o registo detetar.',
  'pet.notMineTitle': 'Marcados «não é meu»: não voltarão a ser propostos.',
  'excl.restore': 'Repor',
  'wz.classNote': 'No EQL podes mudar de trio de classes, e o registo não o notifica em lado nenhum. A aplicação deduz dos feitiços exclusivos que lanças, mas escrever /who depois de cada mudança é o que mantém o histórico correto: é a única coisa que diz o nível e o trio completo.',
  'wz.petNote': 'No EQL o familiar muda de nome em cada invocação, e o registo também não o diz. Escreve /pet who leader quando invocares um novo e ficará reconhecido em todo o histórico; caso contrário aparece como um desconhecido a bater nos teus inimigos.',
  'lvl.mixed': 'Medido nos níveis {levels}. No EQL o teu nível efetivo é o da classe mais baixa do trio, por isso trocar uma classe baixa-o por inteiro. As resistências ficam juntas: não há amostra para as separar por nível.',
  'lvl.unknown': 'sem nível conhecido',
  'lvl.unknownNote': 'Combates anteriores ao teu primeiro /who: o registo não diz que nível tinhas, e não se supõe.',
  'lvl.level': 'Nível {n}',
  'marks.title': 'As minhas melhores marcas',
  'marks.best': 'melhor',
  'per.title': 'O teu nível ao longo do tempo',
  'per.note': 'Não é uma subida: no EQL trocar uma classe por outra mais baixa BAIXA o teu nível, por isso isto são períodos e a linha vai e vem. Cada um abre o melhor combate que fizeste nele.',
  'per.up': 'subiste de {de} para {a}',
  'per.down': 'desceste de {de} para {a} — mudança de classe, não um retrocesso',
  'per.between': 'entre dois combates separados por {m} min: o registo não diz o instante exato',
  'per.aa': '{n} pontos de perícia',
  'per.gear': '{n} peças',
  'per.compTitle': 'Mesmo nível, momentos diferentes',
  'per.compNote': 'A única comparação que diz alguma coisa. Entre níveis não se compara nada: já sabemos que ao 29 bate-se menos do que ao 50.',
  'per.same': 'Nível {n}, {k} períodos:',
  'book.title': 'O teu livro de feitiços',
  'book.note': 'A tabela acima mede o que lanças. Isto mede o contrário: o que consta que tens e nunca sai. Vem do registo — escrever, memorizar e comprar deixam linha — e não de nenhum ficheiro que tenhas de exportar.',
  'book.known': 'consta que são teus',
  'book.unused': 'nunca lançados',
  'book.allUsed': 'Todos os que constam foram lançados pelo menos uma vez.',
  'book.noRecord': 'E {n} lançados sem constar de onde vieram: de antes deste registo, ou de uma classe anterior. Não estão contados acima.',
  'book.via.escrito': 'escrito',
