  'book.via.memorizado.note': 'Tiveste-o equipado a certa altura. Talvez há muitos níveis.',
  'app.credit': 'Feita por Campeon Delmundo da <SPAIN> Guild, a jogar.',
  'crash.title': 'Algo rebentou',
  'crash.copy': 'Copiar',
  'crash.note': 'Esta parte não pôde ser desenhada. O resto da aplicação continua a funcionar; copia isto se quiseres avisar.',
  'crash.where': 'ao desenhar',
  'crash.async': 'numa tarefa de fundo',
  'row.charmed': `${JERGA.charmed}`,
  'row.charmedNote': 'Enfeitiçaste-o: durante esse tempo lutou por ti. É a mesma criatura que a que tem o seu nome no lado inimigo, noutro momento do combate.',
  'charm.amb': 'De um enfeitiçado, {n} golpes e {d} de dano não se podem atribuir: foram entre duas criaturas do mesmo nome e o registo não diz qual era a tua. Todo o resto vai repartido por quem cada um atingiu, o que está medido.',
  'charm.est': 'Pelo ritmo que cada um levava, uns {d} desses seriam teus — deduzido, e não somado a nenhum número acima.',

  'ally.title': 'Dois dos teus a baterem-se um ao outro',
  'ally.row': '{who} lutou contra o grupo · {s} s',
  'ally.rowNote': '{n} golpes e {d} de dano contra {contra}, do segundo {a} ao {b}.',
  'ally.rowNote_1': 'Um golpe e {d} de dano contra {contra}, no segundo {a}.',
  'ally.note': 'É isto o que está medido: dois membros declarados do teu grupo a baterem-se. Porquê, o registo não o diz em nenhuma linha, por isso aqui também não. Este dano fica fora do total dos teus e fora do do inimigo — bater num dos teus não é produção, e levar um golpe dele não o torna inimigo.',
  'ally.previo': 'A última coisa que o inimigo lançou antes deste troço foi {spell}, de {who}, {s} s antes. É o que estava ao lado; o registo não diz que seja a causa.',
  'ally.previoYa': 'A última coisa que o inimigo lançou antes deste troço foi {spell}, de {who}, nesse mesmo segundo. É o que estava ao lado; o registo não diz que seja a causa.',

  'inc.dedu': 'deduzido por uma regra, não lido no registo',
  'inc.title': 'O que este combate não sabe',
  'inc.unattributed': '{n} de dano real sem dono: um escudo de dano sem possessivo, que o registo não atribui a ninguém. Não entra no total de nenhum lado.',
  'inc.soltado': '{n} de dano em {g} golpes contados como inimigos porque o enfeitiçamento quebrou ao encadear outro. O registo não escreve nada quando isso acontece.',
  'inc.loot': '{n} objetos apanhados com dois cadáveres igualmente possíveis: escolheu-se o mais recente, e podia ser o outro.',
  'inc.note': 'Nada disto é um erro: são os números que o registo não deixa fechar, e aparecem aqui para se saberem em vez de desaparecerem dentro de um total.',
  'ctrl.title': 'Perdeste o comando da tua personagem · {s} s no total',
  'ctrl.row': 'Sem controlo · {s} s (do {a} ao {b})',
  'ctrl.rowMiedo': 'Com medo · {s} s (do {a} ao {b})',
  'ctrl.rara': 'Nem medo nem enfeitiçamento: dentro do troço atacaste o inimigo {n} vezes, e nenhum dos dois o permite. Aqui há algo para olhar.',
  'ctrl.rara_1': 'Nem medo nem enfeitiçamento: dentro do troço atacaste o inimigo uma vez, e nenhum dos dois o permite. Aqui há algo para olhar.',
  'ctrl.nocuenta': 'Estes {s} s não contam nem a favor nem contra ti em nenhum número: nem como tempo parado, nem no veredicto de postura, nem em nenhuma média de atividade. Não os decidiste tu, nem a sua duração.',
  'ctrl.dps': 'O teu dps sobre os {s} s em que tinhas o comando: {a}. Sobre o combate inteiro ({d} s), {b} — o número comparável com outros medidores, e por isso continua a ser o de cima.',
  'ctrl.rowCharm': 'Enfeitiçado · {s} s (do {a} ao {b})',
  'ctrl.charmed': 'Enfeitiçado porque dentro do troço bateste nos teus {n} vezes, {d} de dano. Isso é o que se viu, não o que se supõe.',
  'ctrl.charmed_1': 'Enfeitiçado porque dentro do troço bateste num dos teus, {d} de dano. Isso é o que se viu, não o que se supõe.',
  'ctrl.open': 'O combate acabou com o troço em aberto: o fim é o do combate e não o do registo.',
  'ctrl.note': 'O registo escreve os dois extremos — «You lose control of yourself!» e «You have control of yourself again.» — mas não a causa. O que fizeste lá dentro separa-os, e isso vê-se: com medo não podes agir de todo, logo zero ações é medo; enfeitiçado bates nos teus sem o decidir, logo um golpe neles é enfeitiçamento. Começar a lançar não conta: o jogo recusa a tecla e não acontece nada.',

  'duda.head': 'Este combate está mal contado',
  'duda.compa': 'Dos {total} de dano inimigo, {n} são de {quien}, que é companheiro teu declarado. Foi guardado quando um único golpe dele bastava para o passar para o lado contrário durante o resto do combate.',
  'duda.charm': 'Dos {total} do teu lado, {n} são de {quien}, que era um inimigo: guardado com uma janela de enfeitiçamento mal fechada.',
  'duda.invalida': 'Não confies nestes números: {campos}. O resto está bem, e o teu dano pessoal também.',
  'duda.arregla': 'Corrige-se relendo o teu registo a partir do cartaz de reconstrução, e então esta marca desaparece sozinha. Até lá o combate fica, mas fica dito.',
  'chart.note': 'Cada ponto é UM SEGUNDO, não um golpe: um pico é o segundo em que mais dano se acumulou, seja de uma pancada grande ou de cinco pequenas. As duas linhas partilham a mesma escala, por isso as alturas comparam-se. Passa o rato por cima para ler cada segundo.',
  'chart.dealt': 'feito',
  'chart.healed': 'curado',
  'chart.deaths': 'As marcas em cima são as {n} mortes: entre duas delas há, na verdade, combates distintos que o corte por inatividade juntou num só.',
  'det.andMore': 'E mais {n} que não cabem nesta tabela.',
  'tank.title': 'Aguentar',
  'log.title': 'O registo',
  'rp.title': 'Reproduzir',
  'rp.tipFoot': 'O que leva at\u00e9 {t}, n\u00e3o o total da luta.',
  'rp.cast.medido': '{que}: costuma demorar {esp} s, medido sobre {n} lan\u00e7amentos teus.',
  'rp.cast.pasado': '{que}: costuma demorar {esp} s e desta vez demorou {real}. Algo o atrasou. A dura\u00e7\u00e3o habitual sai de {n} lan\u00e7amentos teus.',
  'rp.cast.ya': 'de imediato',
  'rp.cast.yaNota': 'Sai no mesmo segundo em que \u00e9 lan\u00e7ado: n\u00e3o h\u00e1 barra porque n\u00e3o h\u00e1 nada a percorrer. Medido sobre {n} lan\u00e7amentos.',
  'rp.cast.nose': 'por medir',
  'rp.cast.noseNota': 'N\u00e3o h\u00e1 lan\u00e7amentos suficientes para saber quanto demora: {n} dos oito necess\u00e1rios. Sem barra porque n\u00e3o se sabe, que n\u00e3o \u00e9 o mesmo que ser instant\u00e2neo.',
  'rp.soloCerradas': 'S\u00f3 se podem reproduzir lutas fechadas: a que est\u00e1 a decorrer ainda est\u00e1 a acontecer.',
  'rp.button': 'Reproduzir',
  'rp.vs': 'contra',
  'rp.playHint': 'Reproduzir ou pausar. Tamb\u00e9m com a barra de espa\u00e7o; as setas avan\u00e7am um segundo.',
  'rp.seekHint': 'Clica ou arrasta para ir a um segundo. A silhueta \u00e9 o dano por segundo, a mesma do gr\u00e1fico.',
  'rp.agrupado': 'Acelerado: os golpes de um segundo saem juntos, com o seu \u00d7n',
  'rp.reglas': 'Ao painel de texto sobe o que passa um limiar, e os limiares s\u00e3o estes: cr\u00edticos, mortes, lan\u00e7amentos, atordoamentos e interrup\u00e7\u00f5es, e qualquer segundo acima de {pico} de dano \u2014 tr\u00eas vezes o segundo mediano desta luta, que traz {mediana}.',
  'rp.reglasForma': 'E os golpes acima do p90 da sua pr\u00f3pria habilidade.',
  'rp.reglasSinForma': 'A regra do p90 por habilidade n\u00e3o se aplica: esta luta foi guardada antes de a forma do golpe ser contada.',
