  'rp.f.estado': '{quien}: {que}',
  'rp.noLineas': 'Esta luta j\u00e1 n\u00e3o est\u00e1 no teu registo, por isso n\u00e3o se pode reproduzir. As linhas s\u00e3o a fonte: sem elas, qualquer reprodu\u00e7\u00e3o estaria posta a olho.',
  'log.note': 'As linhas do ficheiro entre o in\u00edcio e o fim desta luta, tal como est\u00e3o. Tudo o que a aplica\u00e7\u00e3o mostra s\u00e3o contas sobre isto.',
  'log.loading': 'A ler o registo\u2026',
  'log.cut': 'H\u00e1 mais {n} linhas que n\u00e3o cabem aqui. Cortam-se pelo fim.',
  'log.noTime': 'Esta luta n\u00e3o guarda a sua hora, por isso n\u00e3o se podem ir buscar as suas linhas.',
  'log.err.sin-fichero': 'O registo j\u00e1 n\u00e3o est\u00e1 onde estava: n\u00e3o h\u00e1 linhas para mostrar.',
  'log.err.fuera-de-rango': 'Esta luta n\u00e3o est\u00e1 no registo que tens aberto. Pode vir de outro ficheiro, ou de um que rodou.',
  'log.err.tramo-malo': 'O intervalo de horas pedido n\u00e3o \u00e9 v\u00e1lido.',
  'log.err.error': 'N\u00e3o foi poss\u00edvel ler o registo.',
  'log.outOfRangeSpan': 'O ficheiro aberto vai de {desde} a {hasta}.',
  'row.pace': 'ritmo',
  'row.paceNote': 'O teu dano dividido pelos segundos em que realmente fizeste alguma coisa. O número grande acima é outra coisa: o dano dividido pelo combate inteiro, que é o que pões no relógio do grupo. Quem entra tarde pode ter um ritmo altíssimo e contribuir pouco.',
  'tank.note': 'Quanto passou e quanto ficou na armadura. NÃO diz se estiveste perto de morrer: o registo não dá a vida de ninguém, por isso 3.000 recebidos são uma tragédia com 3.100 de vida e um passeio com 12.000, e isto não sabe qual das duas.',
  'tank.who': 'quem',
  'tank.stopped': 'o que não entrou',
  'tank.stoppedN': 'parados',
  'tank.absorbed': 'absorvido',
  'tank.inRunes': 'em {n}',
  'tank.runeNote': 'A absorção são runas que comem o golpe inteiro. Tudo o que se mostra aqui vem de {n} delas: é um número bruto e não se tira dele nenhuma percentagem, porque com tão poucas não significaria nada.',
  'casts.title': 'O que cada um lançou',
  'casts.note': 'Um traço por lançamento, colocado no segundo em que aconteceu. Cada linha é um lançador, porque a pergunta costuma ser de quem e não de quando: uma linha meio vazia é alguém que não estava a usar o que tem. Passa o rato por um traço para ver qual foi.',
  'casts.cut': 'E mais {n} lançamentos que não cabem no guardado deste combate.',
  'up.title': 'Quanto tempo esteve ativo',
  'up.note': 'Medido do teu lançamento à sua queda, e não da entrada à queda: a linha de queda diz de que feitiço é, a de entrada não diz de nenhum. Relançar antes de cair não conta duas vezes.',
  'up.before': 'já ativo',
  'up.beforeNote': 'Caiu dentro deste combate mas não consta que o tenhas lançado nele: já vinha ativo, por isso conta desde o início.',
  'up.open': 'sem cair',
  'up.openNote': 'Lançaste-o e não caiu antes de acabar o combate. Se tivesse caído haveria linha, por isso conta até ao fim.',
  'up.blind': 'O que não foi lançado nem caiu dentro deste combate não aparece: um buff colocado antes e ainda ativo no fim não deixa nenhuma linha aqui, e não conta nem como 0% nem como 100%. E não se mede mana nem vigor, que o registo do EQL não os dá.',
  'marks.openNote': 'Cada marca abre o combate em que a fizeste: carrega numa e vê-se inteira em Combate.',
  'marks.onlyOne': 'um só combate',
  'marks.median': 'mediana',
  'marks.note': 'Agrupadas por nível de propósito: comparar um combate de hoje com o recorde de quando estavas mais alto só informa que já não estás nesse nível.',
  'foe.byDiff': 'Por dificuldade',
  'foe.castIn': 'O que lançou nos {n} encontros',
  'foe.castIn_1': 'O que lançou no único encontro',
  'foe.castNote': 'No EQL as classes secundárias de um inimigo são sorteadas por instância, por isso dois encontros com o mesmo nome podem ser inimigos diferentes. E algo não aparecer não prova que não o tenha: os NPC respeitam tempos de reutilização. Daí «em quantos de quantos», em vez de uma lista das suas habilidades.',
  'foe.inFights': 'em {n} de {total}',
  'foe.diffNote': 'No EQL cada instância tem uma dificuldade e os inimigos mudam mesmo: mais vida, mais dano e feitiços que nas dificuldades baixas não têm. Fazer a média descreveria um inimigo que não existe.',
  'foe.noDiff': 'sem dificuldade',
  'foe.resistNote': 'As resistências ficam juntas de propósito: no que foi medido mal se distinguem entre dificuldades, e separá-las partiria uma amostra já curta.',
  'cat.title': 'Catálogo de feitiços',
  'cat.open': 'Ver os meus feitiços',
  'cat.note': 'Construído só a partir dos teus combates. O registo não dá o custo em mana nem o tempo de lançamento, e do que nunca lançaste não há nada.',
  'cat.spell': 'Feitiço',
