  'cat.dsNote': 'Não é algo que lances: dispara sozinho quando te batem. Por isso não tem ritmo de uso nem tempo de recarga.',
  'cat.unknownHealNote': 'O registo não disse de que feitiço veio esta cura. Não é um feitiço chamado «cura»: é o que não se conseguiu identificar.',
  'cat.alsoHeals': 'Também cura {n}. Vem das linhas de cura, que até agora não se liam aqui.',
  'cat.drainNote': 'Faz as duas coisas, e as duas estão medidas. Contar só o dano descreve metade do que faz.',
  'cat.levelsNote': 'Usaste-o nos níveis {levels}. Os números vão separados por nível: juntá-los mediria o salto de nível, não o feitiço.',
  'cat.byTranche': 'Troço a troço',
  'cat.trancheNote': 'Uma barra por combate, por ordem mas sem escala de tempo: entre dois combates podem passar dez segundos ou dois dias. Separado por nível e dificuldade, e só com {n} combates ou mais.',
  'cat.noTranche': 'Nenhum troço chega a {n} combates, por isso não se desenha nenhum. Abaixo disso há pontos, não tendência.',
  'cat.dropped': '{n} troços de fora por amostra curta, {f} combates no total',
  'cat.vsFoes': 'Contra quem entra',
  'cat.vsFoesNote': 'Cada inimigo com a sua dificuldade ao lado: o mesmo feitiço pode entrar sempre em D0 e ser resistido em D4.',
