  'tg.aviso.plantillas': 'Os modelos são exemplos que funcionam, não regras verificadas. Os que nomeiam um chefe têm de ser verificados contra o teu próprio registo: põe o chefe que combates e vê se o contador sobe.',
  'tg.ejemplo': 'exemplo',
  'tg.ejemploHint': 'Linha de exemplo para testar o padrão. Não é um disparador guardado nem sai do teu registo: é uma linha real do EverQuest para veres a forma.',
  'tg.note.castAny': 'Inservível assim: num combate com reforços dispara dezenas de vezes. Para feitiços importantes usa «Feitiços inimigos» nas definições de voz, que filtra por categoria e só avisa de inimigos. Este modelo é para vigiar UM em concreto.',
  'tg.note.bossCast': 'Muda o nome para o do chefe que combates. Sem temporizador de propósito: o registo não escreve o tempo de reutilização de um feitiço inimigo em nenhuma linha, por isso não se pode ler — tens de o cronometrar a jogar e pô-lo aqui.',
  'tg.note.petDead': 'A morte do teu familiar já é anunciada sozinha nas definições de voz. Este modelo é para vigiar alguém em concreto: põe o nome exacto ou dispara com qualquer morte.',
  'tg.patternHelp': 'Com ${1}\u2026${9} inseres os grupos capturados na voz e no texto, e ${line} é a linha inteira. O EQL nomeia o feitiço no registo, por isso ^Lady Vox begins casting (.+?)\\.$ dá-te o feitiço em ${1}.',
