  'wz.1.title': 'Bem-vindo',
  'wz.1.body': 'Isto mede o teu dano em tempo real, diz-te que postura convém segundo o que te bate, lê o chat em voz alta e analisa os combates grandes para mostrar o que podia ter corrido melhor.',
  'wz.1.lang': 'Escolhe o teu idioma',
  'wz.1.time': 'A configuração leva dois minutos.',
  'wz.2.title': 'Ativa o registo no jogo',
  'wz.2.body': 'O EverQuest não escreve nada no disco até lho pedires. Sem este passo não há nada para ler.',
  'wz.2.cmd': 'Escreve isto no chat do jogo',
  'wz.2.filters': 'E agora o importante: Options \u2192 Filters',
  'wz.2.filtersBody': 'Põe TUDO o que tenha a ver com dano no máximo detalhe, o teu e o dos outros. Se o dano alheio ficar em «abreviado», o jogo não o escreve e o teu grupo aparece a zero. É o erro mais comum e o mais difícil de detetar, porque a aplicação parece funcionar.',
  'wz.2.done': 'Já o fiz',
  'wz.3.title': 'Encontra o teu ficheiro de registo',
  'wz.3.body': 'Procura-se sozinho em todas as unidades. Com vários personagens, escolhe o que estás a jogar: o nome do ficheiro traz o personagem e o servidor.',
  'wz.3.none': 'Não encontrei nada. Confirma que escreveste /log on e jogaste um momento, ou procura-o à mão.',
  'wz.3.history': 'Ler também os combates já gravados',
  'wz.4.title': 'Diz-me as tuas classes',
  'wz.4.body': 'Cada classe tem umas posturas e não outras. Sem elas não posso aconselhar-te, e deduzi-las do registo nem sempre é possível: Shadow Knight e Paladino partilham as mesmas e são indistinguíveis.',
  'wz.4.who': 'Escreve /who no jogo e preenchem-se sozinhas. Já estou a ler o teu registo.',
  'wz.4.read': 'Lidas do teu /who: {classes}',
  'wz.4.waiting': 'À espera que escrevas /who\u2026',
  'wz.5.title': 'O teu familiar',
  'wz.5.body': 'No EQL o familiar muda de nome a cada invocação, por isso não pode ser reconhecido de memória.',
  'wz.5.cmd': 'Escreve isto uma vez com o familiar fora',
  'wz.5.body2': 'Responderá dizendo quem é o dono e fica identificado. Se não o fizeres, a aplicação perguntará quando detetar alguém a lutar ao teu lado. Sem familiar? Salta este passo.',
  'wz.6.title': 'O overlay',
  'wz.6.body': 'Uma janela pequena sempre por cima do jogo com os números em direto. Esbate-se fora de combate e avisa se a tua postura não for a melhor.',
  'wz.6.fullscreen': 'Precisa do EQL em janela ou sem bordas: o Windows não desenha nada por cima do ecrã inteiro exclusivo.',
  'wz.6.open': 'Abrir o overlay agora',
  'wz.6.ready': 'Pronto. Bate em algo e os números aparecem sozinhos.',
