  'enc.progressNote': 'Não há curva de dps ao longo do tempo, e é de propósito: sobe ao subir de nível e desce ao combater algo mais duro, por isso mede as duas coisas ao mesmo tempo e nenhuma. O comparável é o mesmo inimigo, na mesma dificuldade e no mesmo nível.',
